contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 value, bytes calldata data) public payable {
        // No Ether is required from the test contract because C sends its own balance.
        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Target any address (use this contract), value strictly greater than C's current balance.
        require(value > beforeBalance);

        bool reverted;
        c.sendMoney(address(this), value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterBalance == beforeBalance && afterCount == beforeCount);
    }

    receive() external payable {}
}

