pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value, bytes memory data) internal {
        uint256 beforeBalance = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        vm.assume(value > beforeBalance);
        bool reverted;
        try c.sendMoney(address(this), value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(!reverted && afterBalance == beforeBalance && afterCount == beforeCount);
    }

    function testFuzz_run(uint256 value, bytes memory data) public {
        _run(value, data);
    }

    receive() external payable {}
}
